const getWindowRecoveryMillis = `-- name: GetWindowRecoveryMillis :one
WITH attempt_events AS (
    SELECT
        attempt.id,
        attempt.request_measurement_id,
        attempt.attempt_index,
        attempt.outcome = 'succeeded' AS succeeded,
        attempt.observed_at AS event_at
    FROM measurement_attempts attempt
    JOIN measurement_requests request ON request.id = attempt.request_measurement_id
    WHERE request.site_id = $1
      AND request.is_current
      AND request.source = 'real_traffic'
      AND attempt.supplier_id = $2
      AND attempt.model = $3
      AND attempt.observed_at >= $4
      AND attempt.observed_at < $5
      AND (
          attempt.outcome = 'succeeded'
          OR attempt.error_responsibility = 'supplier'
      )
), ordered AS (
    SELECT
        id,
        succeeded,
        event_at,
        MIN(event_at) FILTER (WHERE succeeded) OVER (
            ORDER BY event_at, request_measurement_id, attempt_index, id
            ROWS BETWEEN 1 FOLLOWING AND UNBOUNDED FOLLOWING
        ) AS recovered_at
    FROM attempt_events
), failure_episodes AS (
    SELECT recovered_at, MIN(event_at) AS failure_at
    FROM ordered
    WHERE NOT succeeded
    GROUP BY recovered_at
), recovery_durations AS (
    SELECT ROUND(EXTRACT(EPOCH FROM (
        (CASE
            WHEN recovered_at IS NULL THEN $5
            ELSE recovered_at
        END) - failure_at
    )) * 1000) AS recovery_millis
    FROM failure_episodes
    WHERE failure_at < $5
      AND (recovered_at IS NULL OR recovered_at > $4)
)
SELECT COALESCE(
    MAX(recovery_millis),
    0
)::bigint AS recovery_millis
FROM recovery_durations
`

type GetWindowRecoveryMillisParams struct {
	SiteID      pgtype.UUID        `json:"site_id"`
	SupplierID  pgtype.UUID        `json:"supplier_id"`
	Model       string             `json:"model"`
	WindowStart pgtype.Timestamptz `json:"window_start"`
	WindowEnd   pgtype.Timestamptz `json:"window_end"`
}

func (q *Queries) GetWindowRecoveryMillis(ctx context.Context, arg GetWindowRecoveryMillisParams) (int64, error) {
	row := q.db.QueryRow(ctx, getWindowRecoveryMillis,
		arg.SiteID,
		arg.SupplierID,
		arg.Model,
		arg.WindowStart,
		arg.WindowEnd,
	)
	var recovery_millis int64
	err := row.Scan(&recovery_millis)
	return recovery_millis, err
}

const listLatestScoreSnapshots = `-- name: ListLatestScoreSnapshots :many
SELECT
    snapshot.id, snapshot.site_id, snapshot.supplier_id, snapshot.model, snapshot.policy_version, snapshot.window_start, snapshot.window_end, snapshot.facts_through, snapshot.passive_samples, snapshot.active_samples, snapshot.price_score, snapshot.latency_score, snapshot.sla_score, snapshot.quality_score, snapshot.total_score, snapshot.confidence, snapshot.eligibility, snapshot.hard_reasons, snapshot.explanation, snapshot.authenticity_assessment_id, snapshot.capability_assessment_id, snapshot.created_at, snapshot.score_run_id,
    supplier.name AS supplier_name,
    COALESCE(authenticity.verdict, 'insufficient')::text AS authenticity_verdict,
    COUNT(*) OVER()::bigint AS total_count
FROM score_snapshots snapshot
JOIN suppliers supplier ON supplier.id = snapshot.supplier_id
LEFT JOIN authenticity_assessments authenticity ON authenticity.id = snapshot.authenticity_assessment_id
WHERE snapshot.id IN (
    SELECT DISTINCT ON (site_id, supplier_id, model) id
    FROM score_snapshots
    ORDER BY site_id, supplier_id, model, created_at DESC, id DESC
)
  AND ($1::uuid IS NULL OR snapshot.site_id = $1::uuid)
  AND ($2::uuid IS NULL OR snapshot.supplier_id = $2::uuid)
  AND ($3::text IS NULL OR snapshot.model = $3::text)
ORDER BY snapshot.created_at DESC, snapshot.id DESC
LIMIT $5 OFFSET $4
`

