const updateScoringAggregationState = `-- name: UpdateScoringAggregationState :execrows
UPDATE scoring_aggregation_state
SET initialized_at = COALESCE(initialized_at, $1),
    facts_through = GREATEST(COALESCE(facts_through, $2), $2),
    updated_at = $3
WHERE name = 'minute_metrics_v1'
`

type UpdateScoringAggregationStateParams struct {
	InitializedAt pgtype.Timestamptz `json:"initialized_at"`
	FactsThrough  pgtype.Timestamptz `json:"facts_through"`
	UpdatedAt     pgtype.Timestamptz `json:"updated_at"`
}

func (q *Queries) UpdateScoringAggregationState(ctx context.Context, arg UpdateScoringAggregationStateParams) (int64, error) {
	result, err := q.db.Exec(ctx, updateScoringAggregationState, arg.InitializedAt, arg.FactsThrough, arg.UpdatedAt)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}
